"""Original Native body footprints and pairwise planar clearances.

The caller supplies actor transforms and bounding boxes from the same Native
frame. A zero planar separation is an overlap cue, not a collision verdict.
"""
import math


def require_finite(value):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError('Nonfinite Native body geometry')
    return float(value)


def footprint(actor):
    box = actor.bounding_box
    ext = box.extent
    if require_finite(ext.x) <= 0 or require_finite(ext.y) <= 0:
        raise ValueError('Native body box has no planar extent')
    pose = actor.get_transform()
    points = []
    for x, y in ((-ext.x, -ext.y), (ext.x, -ext.y),
                 (ext.x, ext.y), (-ext.x, ext.y)):
        local = type(box.location)(x=box.location.x + x,
                                   y=box.location.y + y,
                                   z=box.location.z)
        point = pose.transform(local)
        points.append([require_finite(point.x), require_finite(point.y)])
    return points


def _axes(polygon):
    for first, second in zip(polygon, polygon[1:] + polygon[:1]):
        dx, dy = second[0] - first[0], second[1] - first[1]
        length = math.hypot(dx, dy)
        if length <= 0:
            raise ValueError('Degenerate Native body footprint')
        yield (-dy / length, dx / length)


def _overlap(left, right):
    for ax, ay in list(_axes(left)) + list(_axes(right)):
        a = [x * ax + y * ay for x, y in left]
        b = [x * ax + y * ay for x, y in right]
        if max(a) < min(b) or max(b) < min(a):
            return False
    return True


def _point_segment_distance(point, start, end):
    dx, dy = end[0] - start[0], end[1] - start[1]
    length2 = dx * dx + dy * dy
    if length2 <= 0:
        raise ValueError('Degenerate Native body edge')
    t = max(0.0, min(1.0, ((point[0] - start[0]) * dx +
                            (point[1] - start[1]) * dy) / length2))
    return math.hypot(point[0] - start[0] - t * dx,
                      point[1] - start[1] - t * dy)


def planar_gap(left, right):
    if type(left) is not list or type(right) is not list or len(left) != 4 or len(right) != 4:
        raise ValueError('Four original Native body corners required')
    for polygon in (left, right):
        for point in polygon:
            if len(point) != 2:
                raise ValueError('Invalid Native body corner')
            for value in point:
                require_finite(value)
    if _overlap(left, right):
        return 0.0
    return min(_point_segment_distance(point, a, b)
               for polygon, opposite in ((left, right), (right, left))
               for point in polygon
               for a, b in zip(opposite, opposite[1:] + opposite[:1]))


def constant_velocity_time_to_overlap(left, left_velocity, right,
                                      right_velocity, horizon_s=30):
    """Predicted planar body overlap from same-frame Native velocities.

    This is a kinematic proxy, not an observed collision or legal threshold.
    """
    planar_gap(left, right)
    if (type(left_velocity) is not list or type(right_velocity) is not list or
            len(left_velocity) != 2 or len(right_velocity) != 2):
        raise ValueError('Original Native planar body velocities required')
    for value in left_velocity + right_velocity:
        require_finite(value)
    require_finite(horizon_s)
    if horizon_s <= 0:
        raise ValueError('Positive prediction horizon required')
    relative = [right_velocity[i] - left_velocity[i] for i in (0, 1)]
    entering, leaving = 0.0, float(horizon_s)
    for ax, ay in list(_axes(left)) + list(_axes(right)):
        a = [x * ax + y * ay for x, y in left]
        b = [x * ax + y * ay for x, y in right]
        delta = relative[0] * ax + relative[1] * ay
        if abs(delta) < 1e-12:
            if max(a) < min(b) or max(b) < min(a):
                return None
            continue
        bounds = sorted(((min(a) - max(b)) / delta,
                         (max(a) - min(b)) / delta))
        entering = max(entering, bounds[0])
        leaving = min(leaving, bounds[1])
        if entering > leaving:
            return None
    return max(0.0, entering) if entering <= leaving else None


def scene_clearance(ego, participants):
    own = footprint(ego)
    ego_velocity = ego.get_velocity()
    own_velocity = [require_finite(ego_velocity.x), require_finite(ego_velocity.y)]
    bodies = []
    for actor in participants:
        if actor.id == ego.id:
            continue
        if not (actor.type_id.startswith('vehicle.') or
                actor.type_id.startswith('walker.')):
            continue
        points = footprint(actor)
        velocity = actor.get_velocity()
        participant_velocity = [require_finite(velocity.x), require_finite(velocity.y)]
        bodies.append({'actor_id': int(actor.id), 'type_id': actor.type_id,
                       'footprint_xy_m': points,
                       'velocity_xy_mps': participant_velocity,
                       'planar_gap_m': planar_gap(own, points),
                       'constant_velocity_time_to_overlap_s':
                           constant_velocity_time_to_overlap(
                               own, own_velocity, points, participant_velocity)})
    bodies.sort(key=lambda item: item['actor_id'])
    return {'ego_footprint_xy_m': own, 'ego_velocity_xy_mps': own_velocity,
            'participants': bodies,
            'minimum_surface_gap_m': min((item['planar_gap_m'] for item in bodies),
                                         default=None),
            'minimum_constant_velocity_time_to_overlap_s':
                min((item['constant_velocity_time_to_overlap_s'] for item in bodies
                     if item['constant_velocity_time_to_overlap_s'] is not None),
                    default=None),
            'gap_method': 'original_native_2d_body_footprint_separation',
            'limitation': 'Planar body gap is not a three-dimensional contact or legal judgment.'}


def curbside_lane_info(native_map, location, driving_type, curb_types):
    """Require a source-observed driving lane with a physical roadside neighbor."""
    lane = native_map.get_waypoint(location, project_to_road=False,
                                   lane_type=driving_type)
    if lane is None or lane.lane_type != driving_type:
        raise ValueError('Spawn lacks original Native driving-lane waypoint')
    curb_neighbor = lane.get_right_lane()
    if curb_neighbor is None or curb_neighbor.lane_type not in curb_types:
        raise ValueError('Spawn lacks original Native curbside neighbor')
    return {'road_id': int(lane.road_id), 'section_id': int(lane.section_id),
            'lane_id': int(lane.lane_id),
            'right_neighbor_road_id': int(curb_neighbor.road_id),
            'right_neighbor_lane_id': int(curb_neighbor.lane_id),
            'right_neighbor_type': str(curb_neighbor.lane_type),
            'method': 'native_waypoint_right_lane_source',
            'limitation': 'Adjacent lane topology identifies a curbside candidate; actual curb geometry and municipal jurisdiction require review.'}


def choose_curbside_spawn(native_map, spawns, preferred_index, driving_type, curb_types):
    if type(preferred_index) is not int or preferred_index < 0 or preferred_index >= len(spawns):
        raise ValueError('Preferred Native spawn index unavailable')
    order = [preferred_index] + [index for index in range(len(spawns))
                                 if index != preferred_index]
    for index in order:
        try:
            info = curbside_lane_info(native_map, spawns[index].location,
                                      driving_type, curb_types)
        except ValueError:
            continue
        return index, info
    raise ValueError('No source-observed curbside driving spawn exists in Native map')


def spawn_sidewalk_pedestrian(world, roadside_lane, selector):
    if selector != 'walker.pedestrian.*' or roadside_lane is None:
        raise ValueError('Exact adjacent-sidewalk pedestrian construction required')
    walkers = sorted(world.get_blueprint_library().filter(selector),
                     key=lambda blueprint: blueprint.id)
    if not walkers:
        raise RuntimeError('No Native pedestrian blueprint available')
    pose = roadside_lane.transform
    pose.location.z += 0.3
    walker = world.try_spawn_actor(walkers[0], pose)
    if walker is None:
        raise RuntimeError('Adjacent sidewalk pedestrian spawn unavailable')
    return walker

"""Saved-only C230222 curbside source finalizer, without a legal verdict."""
import argparse
import hashlib
import json
from pathlib import Path

from driving_cues import measure

PREFIX = 'training__C230222__LVMC-11-22-020__motor_vehicle_driver__'
CASES = (PREFIX + 'probe_a', PREFIX + 'probe_b')
VIDEOS = ('overview.mkv', 'approach.mkv', 'reference_corner.mkv',
          'driver_reference.mkv')
SOURCES = ('native-ego-frames.jsonl', 'native-body-geometry.jsonl',
           'native-collision-events.jsonl', 'video_frames.jsonl',
           'driving-context.json', 'trace.jsonl')


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def measure_curbside(rows, source_hashes):
    """Report exact source-derived driving cues, without a legal conclusion."""
    return {
        'sample_count': len(rows),
        'min_planar_gap_m': min((row['minimum_surface_gap_m'] for row in rows
                                 if row['minimum_surface_gap_m'] is not None),
                                default=None),
        'min_constant_velocity_overlap_time_s': min(
            (row['constant_velocity_time_to_conflict_s'] for row in rows
             if row['constant_velocity_time_to_conflict_s'] is not None),
            default=None),
        'source_sha256': source_hashes,
        'legal_carelessness_or_imprudence': None,
    }


def channel_value(name, row, context):
    if name == 'drv.time_to_conflict':
        return {'constant_velocity_planar_body_overlap_s':
                row['constant_velocity_time_to_conflict_s'],
                'legal_cutoff': None}
    if name == 'drv.hard_deceleration':
        return {'longitudinal_acceleration_mps2':
                row['longitudinal_acceleration_mps2'], 'legal_cutoff': None}
    if name == 'kin.yaw_rate':
        return {'yaw_rate_degps': row['yaw_rate_degps']}
    if name == 'kin.speed':
        return {'speed_mps': row['speed_mps']}
    if name == 'rel.surface_gap':
        return {'planar_body_gap_m': row['minimum_surface_gap_m'],
                'three_dimensional_contact_inferred': False}
    if name == 'rel.contact':
        return {'original_collision_event_positive': row['contact'],
                'absence_inferred': False}
    if name == 'st.highway':
        return {'native_map_name': context.get('map_name'),
                'municipal_highway_review': context.get('highway_in_city_evidence')}
    if name == 'ru.pedestrian':
        return {'native_walker_actor_id': context.get('pedestrian_id'),
                'visible_in_original_pixels': row['pedestrian_visible']}
    raise ValueError('Unknown curbside capture channel: ' + name)


def finalize(attempt, output):
    from worker_exchange.native_output import write_result, physical_result

    attempt, output = Path(attempt), Path(output)
    if output.exists() or (attempt / 'result.json').exists():
        raise ValueError('Retain prior analysis; use a fresh attempt')
    for name in (*SOURCES, *VIDEOS, 'config.json', 'construction.json'):
        path = attempt / name
        if not path.is_file():
            raise ValueError('Missing required source: ' + name)
        if name in VIDEOS and path.stat().st_size == 0:
            raise ValueError('Empty required source video: ' + name)
    config = json.loads((attempt / 'config.json').read_text())
    construction = json.loads((attempt / 'construction.json').read_text())
    case_id = config.get('case_id')
    if (case_id not in CASES or construction.get('case_id') != case_id or
            config.get('law_id') != 'LVMC-11-22-020' or
            config.get('cell_id') != 'C230222' or
            config.get('actor') != 'motor_vehicle_driver'):
        raise ValueError('Exact curbside source identity differs')
    context = json.loads((attempt / 'driving-context.json').read_text())
    if context.get('case_id') != case_id:
        raise ValueError('Original driving context case differs')
    measured = measure(attempt)
    rows = measured['measurements']
    channel_descriptors = construction['recording_description']['channels']
    channel_names = [channel.get('name') for channel in channel_descriptors]
    if channel_names != ['drv.time_to_conflict', 'drv.hard_deceleration',
                         'kin.yaw_rate', 'kin.speed', 'rel.surface_gap',
                         'rel.contact', 'st.highway', 'ru.pedestrian']:
        raise ValueError('Curbside channel contract differs')
    channels = attempt / 'channels'
    channels.mkdir(exist_ok=False)
    for name in channel_names:
        channel = channels / (name + '.jsonl')
        with channel.open('x') as stream:
            for row in rows:
                stream.write(json.dumps({'time_s': row['time_s'],
                                         'value': channel_value(name, row, context)},
                                        allow_nan=False) + '\n')
    source_hashes = {name: sha(attempt / name) for name in SOURCES}
    physical_flags = ['Physical curbside travel, pedestrian visibility and municipal highway status require original review']
    result = {
        'case_id': case_id,
        'measured_values': {
            'sample_count': 600, 'sampling_rate_hz': 20,
            'min_observed_planar_gap_m': min((row['minimum_surface_gap_m'] for row in rows
                                          if row['minimum_surface_gap_m'] is not None),
                                         default=None),
            'min_constant_velocity_time_to_conflict_s':
                min((row['constant_velocity_time_to_conflict_s'] for row in rows
                     if row['constant_velocity_time_to_conflict_s'] is not None),
                    default=None),
            'source_sha256': source_hashes,
            'legal_carelessness_or_imprudence': None,
        },
        'target_checks': [{
            'target': 'original curbside source streams time joined',
            'requested': True, 'measured': True,
            'method': 'driving_cues.measure', 'tolerance': 0,
            'matched': True, 'physical_cause_confirmed': False,
            'cause_evidence': list(SOURCES),
        }],
        'setup_confirmed': False, 'behavior_attempted': False,
        'maneuver_completed': False,
        'termination_reason': '600 source frames measured; physical review pending',
        'physical_failure_flags': physical_flags,
        'trace_reference': 'trace.jsonl', 'video_references': list(VIDEOS),
        'video_frame_map_reference': 'video_frames.jsonl',
        'recording_description': construction['recording_description'],
        'recording_evidence': [{
            'name': name, 'unit': 'structured',
            'reference': 'channels/' + name + '.jsonl',
        } for name in channel_names],
        'realized_observables': {},
        'provenance_kind': 'native' if measured['source_kind'] == 'original_native' else 'synthetic_fixture',
        'diagnostic_fixture': measured['source_kind'] != 'original_native',
        'physical_acceptance_claimed': False,
        'legal_acceptance_claimed': False,
    }
    result = physical_result(attempt, result)
    write_result(attempt, result)
    report = {
        'format': 'worker-analysis-report', 'case_id': case_id,
        'measurements': {'curbside_manner_measurement': {
            'method': 'measure_curbside',
            'value': measure_curbside(rows, source_hashes),
            'sources': source_hashes,
        }},
        'physical_checks': result['physical_checks'],
        'realized_observables': result['realized_observables'],
        'physical_or_legal_acceptance': False,
    }
    output.write_text(json.dumps(report, indent=2) + '\n')
    return report


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    finalize(args.attempt, args.output)

import copy
import json
import unittest
from pathlib import Path
from runner import FRAMES, RATE, check, phase_at
from body_geometry import choose_curbside_spawn, scene_clearance, spawn_sidewalk_pedestrian

class Vec:
    def __init__(self, x, y, z=0):
        self.x, self.y, self.z = x, y, z

class Box:
    def __init__(self):
        self.location, self.extent = Vec(0, 0), Vec(1, 0.5)

class Pose:
    def __init__(self, x, y, yaw=0):
        self.x, self.y, self.yaw = x, y, yaw
    def transform(self, point):
        import math
        angle = math.radians(self.yaw)
        return Vec(self.x + point.x * math.cos(angle) - point.y * math.sin(angle),
                   self.y + point.x * math.sin(angle) + point.y * math.cos(angle))

class Actor:
    def __init__(self, actor_id, x, y, yaw=0, kind='vehicle.test'):
        self.id, self.type_id = actor_id, kind
        self.bounding_box = Box()
        self.pose = Pose(x, y, yaw)
    def get_transform(self):
        return self.pose
    def get_velocity(self):
        return Vec(0, 0)

class Lane:
    def __init__(self, lane_type, right=None):
        self.lane_type, self.right = lane_type, right
        self.road_id, self.section_id, self.lane_id = 1, 0, -1
    def get_right_lane(self):
        return self.right

class Map:
    def __init__(self, lanes):
        self.lanes = lanes
    def get_waypoint(self, location, *, project_to_road, lane_type):
        assert project_to_road is False
        assert lane_type == 'Driving'
        return self.lanes[location]

class Spawn:
    def __init__(self, location):
        self.location = location

class Blueprint:
    id = 'walker.pedestrian.0001'

class Library:
    def filter(self, selector):
        assert selector == 'walker.pedestrian.*'
        return [Blueprint()]

class World:
    def __init__(self):
        self.created = None
    def get_blueprint_library(self):
        return Library()
    def try_spawn_actor(self, blueprint, pose):
        self.created = (blueprint.id, pose.location.z)
        return Actor(9, 2, 2, kind='walker.pedestrian.0001')

class ExactCaptureContract(unittest.TestCase):
    def setUp(self):
        self.config = json.loads(Path('config.json').read_text())

    def test_window_and_cameras(self):
        result = check(self.config)
        self.assertEqual((result['frames'], result['rate_hz']), (600, 20))
        self.assertEqual(len(result['camera_views']), 4)
        self.assertEqual(len([phase_at(self.config, i) for i in range(FRAMES)]), 600)
        self.assertIsNone(result['legal_verdict'])

    def test_reject_missing_camera(self):
        bad = copy.deepcopy(self.config)
        bad['cameras'].pop()
        with self.assertRaisesRegex(ValueError, 'Four named'):
            check(bad)

    def test_reject_short_or_discontinuous_schedule(self):
        bad = copy.deepcopy(self.config)
        bad['control_phases'][-1]['last_frame'] = 598
        with self.assertRaises(ValueError):
            check(bad)
        bad = copy.deepcopy(self.config)
        bad['control_phases'][1]['first_frame'] += 1
        with self.assertRaises(ValueError):
            check(bad)

    def test_reject_invented_legal_verdict(self):
        bad = copy.deepcopy(self.config)
        bad['legal_verdict'] = 'careless'
        with self.assertRaises(ValueError):
            check(bad)

    def test_endpoint_rejection(self):
        with self.assertRaises(ValueError):
            phase_at(self.config, FRAMES)

    def test_original_body_clearance_both_directions(self):
        ego = Actor(1, 0, 0)
        ahead = Actor(2, 4, 0)
        behind = Actor(3, -4, 0)
        for other in (ahead, behind):
            result = scene_clearance(ego, [ego, other])
            self.assertAlmostEqual(result['minimum_surface_gap_m'], 2)
            self.assertEqual(len(result['participants']), 1)
        overlapping = scene_clearance(ego, [Actor(4, 0.5, 0.1, 30)])
        self.assertEqual(overlapping['minimum_surface_gap_m'], 0)

    def test_unknown_gap_without_source_participant(self):
        ego = Actor(1, 0, 0)
        sensor = Actor(7, 0, 0, kind='sensor.camera.rgb')
        result = scene_clearance(ego, [ego, sensor])
        self.assertIsNone(result['minimum_surface_gap_m'])
        self.assertEqual(result['participants'], [])

    def test_selects_source_observed_curbside_lane(self):
        spawns = [Spawn(0), Spawn(1)]
        native_map = Map([Lane('Driving'), Lane('Driving', Lane('Sidewalk'))])
        selected, info = choose_curbside_spawn(native_map, spawns, 0,
                                               'Driving', ('Sidewalk', 'Shoulder', 'Parking'))
        self.assertEqual(selected, 1)
        self.assertEqual(info['right_neighbor_type'], 'Sidewalk')
        with self.assertRaisesRegex(ValueError, 'No source-observed curbside'):
            choose_curbside_spawn(Map([Lane('Driving'), Lane('Driving')]),
                                  spawns, 0, 'Driving', ('Sidewalk',))

    def test_creates_sidewalk_pedestrian_from_native_lane(self):
        world = World()
        lane = Lane('Sidewalk')
        lane.transform = type('Transform', (), {'location': Vec(2, 2, 0)})()
        walker = spawn_sidewalk_pedestrian(world, lane, 'walker.pedestrian.*')
        self.assertEqual(walker.type_id, 'walker.pedestrian.0001')
        self.assertEqual(world.created, ('walker.pedestrian.0001', 0.3))
        with self.assertRaisesRegex(ValueError, 'Exact adjacent-sidewalk'):
            spawn_sidewalk_pedestrian(world, lane, 'vehicle.*')
